'use strict';
const $=id=>document.getElementById(id);
const state={layout:'portrait',labelSelection:null,rows:null,sheets:[],fileName:'',demo:false,data:null,revision:0,exporting:false};
const localDate=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
$('cutoff').value=localDate();
const assets=Promise.all([fetch('data/airports.json').then(checkResponse).then(r=>r.json()),fetch('data/world.json').then(checkResponse).then(r=>r.json()),fetch('templates/portrait.html').then(checkResponse).then(r=>r.text())]);
function checkResponse(r){if(!r.ok)throw Error('地图资源加载失败，请刷新页面重试。');return r;}
function status(message,type=''){$('status').textContent=message;$('status').className='status '+type;}
function error(e){status(e.message||String(e),'error');}
const alias={date:['date','日期','航班日期','出发日期','飞行日期'],from:['from','origin','departureairport','出发机场','起飞机场','出发地','起点'],to:['to','destination','arrivalairport','到达机场','抵达机场','目的地','终点'],airline:['airline','airlinecode','航空公司','航司','航司代码'],flight:['flight','flightnumber','航班号','航班'],canceled:['canceled','cancelled','取消','是否取消'],aircraft:['aircrafttypename','aircraft','机型','飞机型号']};
const cleanHeader=s=>String(s??'').replace(/^\uFEFF/,'').trim().toLowerCase().replace(/[\s_\-()（）]/g,'');
function headerMap(row){const m={};for(const [i,h] of row.entries())for(const [key,options] of Object.entries(alias))if(options.includes(cleanHeader(h))&&m[key]===undefined)m[key]=i;return m;}
function parseSheet(matrix,name){for(let index=0;index<Math.min(matrix.length,20);index++){const mapping=headerMap(matrix[index]);if(['date','from','to'].every(k=>mapping[k]!==undefined)){const rows=matrix.slice(index+1).map((r,i)=>{const row={_line:index+i+2};for(const [key,j] of Object.entries(mapping))row[key]=r[j]??'';return row;}).filter(r=>[r.date,r.from,r.to,r.airline,r.flight].some(v=>String(v).trim()));return {name,rows};}}return null;}
function dateValue(v){if(v instanceof Date){if(Number.isNaN(v.getTime()))return null;return `${v.getFullYear()}-${String(v.getMonth()+1).padStart(2,'0')}-${String(v.getDate()).padStart(2,'0')}`;}if(typeof v==='number'){const p=XLSX.SSF.parse_date_code(v);if(!p)return null;return validDate(`${p.y}-${String(p.m).padStart(2,'0')}-${String(p.d).padStart(2,'0')}`);}const s=String(v).trim();const m=s.match(/^(\d{4})[-/.年](\d{1,2})[-/.月](\d{1,2})(?:日|\b|T)/);if(m)return validDate(`${m[1]}-${m[2].padStart(2,'0')}-${m[3].padStart(2,'0')}`);return null;}
function validDate(s){const d=new Date(s+'T12:00:00Z');return !Number.isNaN(d.getTime())&&d.toISOString().slice(0,10)===s?s:null;}
function airportCode(v){return String(v??'').trim().toUpperCase();}
function uniqueFlightRows(rows,latestAircraft=false){const result=[],seen=new Map();let duplicates=0;for(const original of rows){const row={...original,airline:normalizeAirlineCode(original.airline),from:airportCode(original.from),to:airportCode(original.to),flight:String(original.flight??'').trim()},date=dateValue(row.date);if(date)row.date=date;const key=date&&row.from&&row.to?JSON.stringify([date,row.airline,row.flight,row.from,row.to]):null;if(key&&seen.has(key)){duplicates++;const earlier=seen.get(key);const aircraft=String(row.aircraft||'').trim();if(aircraft&&(latestAircraft||!String(earlier.aircraft||'').trim()))earlier.aircraft=aircraft;continue;}result.push(row);if(key)seen.set(key,row);}return {rows:result,duplicates};}
function normalizeFlightStore(){if(state.rows===null&&!state.sheets.length)return;const source=state.sheets.length>1?state.sheets.flatMap(s=>s.rows):state.rows||[];const unique=uniqueFlightRows(source);if(source!==state.rows||unique.duplicates){if(state.rows&&source===state.rows)state.rows.splice(0,state.rows.length,...unique.rows);else state.rows=unique.rows;}state.sheets=[{name:'航班记录',rows:state.rows}];$('sheet-wrap').hidden=true;$('sheet').replaceChildren(new Option('航班记录','0'));}
let importQueue=Promise.resolve();
function loadFile(file){const task=()=>importFlightFile(file);importQueue=importQueue.then(task,task);return importQueue;}
async function importFlightFile(file){if(!file)return;if(file.size>20*1024*1024){error(Error('文件超过 20 MB，请减小文件后重试。'));return;}if(!/\.(csv|xlsx|xls)$/i.test(file.name)){error(Error('请选择 .csv、.xlsx 或 .xls 文件。'));return;}status('正在读取文件…','busy');try{let sheets=[];if(/\.csv$/i.test(file.name)){const parsed=d3.csvParseRows((await file.text()).replace(/^\uFEFF/,''));const sheet=parseSheet(parsed,'CSV');if(sheet)sheets.push(sheet);}else{const wb=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:true});for(const name of wb.SheetNames){const sheet=parseSheet(XLSX.utils.sheet_to_json(wb.Sheets[name],{header:1,defval:'',raw:true}),name);if(sheet)sheets.push(sheet);}}
 if(!sheets.length)throw Error('未找到可识别的航班表。请检查表头是否包含“日期、出发机场、到达机场”，机场请使用三字码。');
 if(typeof draftRestoreReady!=='undefined')await draftRestoreReady;normalizeFlightStore();const incoming=sheets.flatMap(s=>s.rows),before=state.rows?.length||0,previous=new Map((state.rows||[]).map(r=>[JSON.stringify([dateValue(r.date),normalizeAirlineCode(r.airline),String(r.flight??'').trim(),airportCode(r.from),airportCode(r.to)]),String(r.aircraft||'').trim()])),merged=uniqueFlightRows([...(state.rows||[]),...incoming],true);const updated=merged.rows.filter(r=>{const key=JSON.stringify([dateValue(r.date),r.airline,r.flight,r.from,r.to]);return previous.has(key)&&String(r.aircraft||'').trim()!==previous.get(key);}).length;state.rows=merged.rows;state.sheets=[{name:'航班记录',rows:state.rows}];state.fileName=file.name;state.demo=false;$('file-info').textContent=file.name;$('sheet-wrap').hidden=true;await regenerate();const added=state.rows.length-before,skipped=incoming.length-added-updated;$('import-result').textContent=`成功新增 ${added} 条航班记录${updated?`，更新 ${updated} 条机型`:''}${skipped?`，跳过 ${skipped} 条重复记录`:''}。`;
 }catch(e){error(e);}finally{$('file').value='';}}
function calculate(rows,airports,cutoff,includeFuture){const flights=[],seen=new Map(),unknown=new Set(),unknownAirlines=new Set(),invalid=[],meta={duplicates:0,future:0,canceled:0,missingAirline:0,missingFlight:0};
 for(const row of rows){const date=dateValue(row.date),from=airportCode(row.from),to=airportCode(row.to);if(!date||!from||!to){invalid.push(row._line);continue;}const canceled=['true','1','是','yes','已取消'].includes(String(row.canceled).trim().toLowerCase());if(canceled){meta.canceled++;continue;}if(!includeFuture&&date>cutoff){meta.future++;continue;}const airline=normalizeAirlineCode(row.airline),flight=String(row.flight??'').trim();const key=[date,airline,flight,from,to].join('|');if(seen.has(key)){const earlier=seen.get(key);if(earlier.aircraft&&row.aircraft&&earlier.aircraft!==String(row.aircraft).trim())throw Error(`第 ${row._line} 行与同航班记录机型冲突，请核对后重新上传。`);meta.duplicates++;continue;}if(!validAirlineCode(airline))unknownAirlines.add(airline);const f={Date:date,Airline:airline,Flight:flight,From:from,To:to,aircraft:String(row.aircraft??'').trim()};seen.set(key,f);if(!airports[from])unknown.add(from);if(!airports[to])unknown.add(to);if(!airline)meta.missingAirline++;if(!flight)meta.missingFlight++;flights.push(f);}
 if(invalid.length)throw Error(`第 ${invalid.slice(0,8).join('、')} 行缺少有效日期或机场代码。请修正后重新上传，避免漏算。日期建议为 YYYY-MM-DD。`);
 if(unknownAirlines.size)throw Error(`未识别航司的 IATA 两位代码：${[...unknownAirlines].join('、')}。请在下方记录中编辑航司，填写如 MU、CZ、CA 的两位代码。`);
 if(unknown.size)throw Error(`未识别机场：${[...unknown].slice(0,12).join('、')}。请使用三字机场代码，如 SHA、NRT；当前地图没有生成，以免漏掉行程。`);
 if(!flights.length)throw Error(`没有符合日期范围的航班记录。可调整截止日期或勾选“同时计入未来行程”。`);
 const used={},routes=new Map();for(const f of flights){for(const code of [f.From,f.To]){if(!used[code])used[code]={...airports[code],xy:[...airports[code].xy],n:0};used[code].n++;}const pair=[f.From,f.To].sort(),key=pair.join('|');if(!routes.has(key))routes.set(key,{a:pair[0],b:pair[1],flights:[]});routes.get(key).flights.push(f);}
 const rs=[...routes.values()];for(const r of rs)r.km=d3.geoDistance(used[r.a].xy,used[r.b].xy)*6371.0088;
 const legs=rs.flatMap(r=>r.flights.map(f=>({a:f.From,b:f.To,km:r.km,date:f.Date,airline:f.Airline,flight:f.Flight}))).sort((a,b)=>{for(const key of ['date','airline','flight','a','b']){if(a[key]<b[key])return -1;if(a[key]>b[key])return 1;}return 0;});
 const uniqueLegs=[...new Map([...legs].reverse().map(r=>[[r.a,r.b].sort().join('|'),r])).values()];
 const longestRoutes=[...uniqueLegs].sort((a,b)=>b.km-a.km||legs.indexOf(a)-legs.indexOf(b)).slice(0,2),shortestRoutes=[...uniqueLegs].sort((a,b)=>a.km-b.km||legs.indexOf(a)-legs.indexOf(b)).slice(0,2);
 const codes=Object.keys(used).sort(),north=codes.reduce((a,c)=>used[c].xy[1]>used[a].xy[1]?c:a),south=codes.reduce((a,c)=>used[c].xy[1]<used[a].xy[1]?c:a),east=codes.reduce((a,c)=>used[c].xy[0]>used[a].xy[0]?c:a),west=codes.reduce((a,c)=>used[c].xy[0]<used[a].xy[0]?c:a);
 return {longestRoutes,shortestRoutes,airports:used,routes:rs,total:flights.length,airlineCount:new Set(flights.map(f=>f.Airline).filter(Boolean)).size,busiest:codes.reduce((a,c)=>used[c].n>used[a].n?c:a),extremes:{north,south,east,west},totalKm:Math.round(rs.reduce((n,r)=>n+r.km*r.flights.length,0)),meta};}
function jsonInline(value){return JSON.stringify(value).replace(/</g,'\\u003c');}
async function regenerate(){$('cutoff').value=localDate();normalizeFlightStore();for(const row of state.rows||[])row.airline=normalizeAirlineCode(row.airline);window.dispatchEvent(new CustomEvent('atlas:rows'));const revision=++state.revision;if(!state.rows?.length){state.data=null;if(typeof updateLabelControls==='function')updateLabelControls(null);$('download').disabled=true;$('poster-wrap').hidden=true;$('empty').hidden=false;$('preview-tag').textContent='等待添加';status('添加一班航班，开始生成你的地图。');return;}status('正在计算航线与里程…','busy');$('download').disabled=true;try{if(!validDate($('cutoff').value))throw Error('请选择有效的统计截止日期。');const [airports,world,portrait]=await assets;const data=calculate(state.rows,airports,$('cutoff').value,$('future').checked);if(typeof labelNamesReady!=='undefined')await labelNamesReady;if(revision!==state.revision)return;if(typeof getMapLabels==='function'){data.labels=getMapLabels(data);data.airportNames=labelChineseNames;updateLabelControls(data);}data.colors=atlasColors(state.colors);const template=portrait;let html=template.replace('__DATA__',jsonInline(data)).replace('__WORLD__',jsonInline(world));if(!data.airlineCount)html=html.replace('${data.airlineCount}<small>家</small>','未填写');
 $('poster-wrap').hidden=false;$('empty').hidden=true;const frame=$('poster');const loaded=new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('预览加载超时，请刷新后重试。')),30000);frame.onload=async()=>{try{const start=Date.now();while(frame.contentDocument?.querySelector('#poster')?.dataset.ready!=='true'){if(Date.now()-start>25000)throw Error('地图绘制失败，请刷新后重试。');await new Promise(r=>setTimeout(r,80));}clearTimeout(timer);resolve();}catch(e){clearTimeout(timer);reject(e);}};});frame.srcdoc=html;await loaded;if(revision!==state.revision)return;state.data=data;resizePoster();$('preview-tag').textContent='已生成';status(`地图已生成 · ${data.total} 次飞行 · ${data.totalKm.toLocaleString('zh-CN')} km（估算）`);$('download').disabled=false;updateSize();
 }catch(e){if(revision!==state.revision)return;state.data=null;if(typeof updateLabelControls==='function')updateLabelControls(null);$('poster-wrap').hidden=true;$('empty').hidden=false;$('preview-tag').textContent='需要检查文件';error(e);}}
function updateSize(){const size='2160 × 2300';$('export-note').textContent='PNG · '+size;$('image-size').textContent=size+' px';}
function resizePoster(){const frame=$('poster'),stage=$('poster-stage');const w=1080,h=1150;const available=stage.parentElement.clientWidth;const scale=available/w;stage.style.height=(h*scale)+'px';frame.width=String(w);frame.height=String(h);frame.style.width=w+'px';frame.style.height=h+'px';frame.style.transform=`scale(${scale})`;}
new ResizeObserver(resizePoster).observe($('poster-wrap'));
$('file').addEventListener('change',e=>loadFile(e.target.files[0]));
for(const name of ['dragenter','dragover'])$('dropzone').addEventListener(name,e=>{e.preventDefault();$('dropzone').classList.add('dragover');});for(const name of ['dragleave','drop'])$('dropzone').addEventListener(name,e=>{e.preventDefault();$('dropzone').classList.remove('dragover');});$('dropzone').addEventListener('drop',e=>loadFile(e.dataTransfer.files[0]));
$('sheet').addEventListener('change',()=>{state.rows=state.sheets[Number($('sheet').value)].rows;regenerate();});$('cutoff').addEventListener('change',regenerate);$('future').addEventListener('change',regenerate);
$('download').addEventListener('click',async()=>{if(!state.data||state.exporting)return;state.exporting=true;$('download').disabled=true;status('正在生成高清图片…','busy');try{const win=$('poster').contentWindow,poster=win.document.getElementById('poster');await win.document.fonts.ready;
// Preserve SVG paints explicitly: foreignObject snapshots may discard class-based SVG fills.
for(const node of poster.querySelectorAll('svg,svg *')){const style=win.getComputedStyle(node);for(const key of ['fill','stroke','stroke-width','stroke-linecap','stroke-linejoin','opacity','font-family','font-size','font-weight','paint-order','letter-spacing','text-anchor'])node.setAttribute(key,style.getPropertyValue(key));}
const url=await win.htmlToImage.toPng(poster,{pixelRatio:2,fontEmbedCSS:'',cacheBust:false});const a=document.createElement('a');a.href=url;a.download=`flight-atlas-${$('cutoff').value}-${state.layout}.png`;a.click();status('高清图片已生成，下载已开始。');}catch(e){error(Error('图片导出失败，请在 Chrome 或 Edge 中重试。'+(e.message?' '+e.message:'')));}finally{state.exporting=false;$('download').disabled=!state.data;}});
$('sample').addEventListener('click',()=>{const csv='\uFEFFDate,Airline,Flight,From,To\r\n';const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='flight-atlas-template.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);});
assets.then(([,world])=>{const topo=world.objects.countries;const decode=topologyFeatures(world,topo);const svg=d3.select('#empty-world'),projection=d3.geoNaturalEarth1().rotate([-125,0]).fitExtent([[0,10],[900,460]],{type:'Sphere'});svg.selectAll('path').data(decode).join('path').attr('d',d3.geoPath(projection)).attr('fill','#8fa6b8').attr('stroke','#142737').attr('stroke-width',.5);}).catch(error);
function topologyFeatures(t,obj){const arcs=t.arcs.map(arc=>{let x=0,y=0;return arc.map(p=>{x+=p[0];y+=p[1];return [x*t.transform.scale[0]+t.transform.translate[0],y*t.transform.scale[1]+t.transform.translate[1]];});});function ring(ids){const points=[];for(const i of ids){const a=(i<0?[...arcs[~i]].reverse():arcs[i]);points.push(...(points.length?a.slice(1):a));}return points;}return obj.geometries.map(g=>({type:'Feature',geometry:g.type==='Polygon'?{type:'Polygon',coordinates:g.arcs.map(ring)}:{type:'MultiPolygon',coordinates:g.arcs.map(p=>p.map(ring))}}));}

function refreshAtlasDay(){if($('cutoff').value!==localDate()){$('cutoff').value=localDate();if(state.rows)regenerate();}}
window.addEventListener('focus',refreshAtlasDay);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshAtlasDay();});setInterval(refreshAtlasDay,60000);

function dismissOnBackdrop(dialog,canClose=()=>true,onClose=()=>dialog.close()){
 let startedOutside=false;
 const outside=event=>{const box=dialog.getBoundingClientRect();return event.target===dialog&&(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom);};
 dialog.addEventListener('pointerdown',event=>{startedOutside=outside(event);});
 dialog.addEventListener('click',event=>{const dismiss=startedOutside&&outside(event);startedOutside=false;if(dismiss&&canClose())onClose();});
 dialog.addEventListener('close',()=>{startedOutside=false;});
}
